.menu-public::before {
  content: "";
  display: block;
  width: clamp(180px, 26vw, 320px);
  aspect-ratio: 5 / 3;
  margin: 0 auto;
  background-image: url("https://storage.googleapis.com/pej-app/pmd/eatery--logo-1.png");
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
}

