/* =================================================================
   Eatery — lunch menu, custom CSS
   ================================================================= */

@import url("https://fonts.googleapis.com/css2?family=Roboto+Slab:wght@100..900&display=swap");

body {
  margin: 0;
  background-color: #315d6d;
}

/* =================================================================
   SHARED — both surfaces
   ================================================================= */

.menu-public {
  --mp-color-text: #f5f0e3;
  --mp-color-background: transparent;
  --mp-color-today: #fff;

  --mp-fs-h1: clamp(1.3rem, 3.6vw, 2.2rem);
  --mp-fs-h2: clamp(1.35rem, 4.2vw, 2rem);
  --mp-fs-p: clamp(0.95rem, 2.5vw, 1.2rem);
  --mp-lh-p: 1.4;
  /* Weekly only: the description a step under the name. Daily re-states both
     tokens itself and is not affected. */
  --mp-fs-item-description: clamp(0.85rem, 2.2vw, 1.05rem);

  --mp-space-page: 0;
  --mp-dot-size: clamp(8px, 1.1vw, 14px);

  min-height: 100vh;
  box-sizing: border-box;
  /* Top is the air above the logo. On the weekly page it shares its row with the
     title, so it is the page frame that has to give, not the logo's own margin. */
  padding: clamp(2.5rem, 7vw, 5.5rem) clamp(1rem, 4vw, 3rem)
    clamp(2.5rem, 6vw, 4rem);

  text-align: center;
}

/* Cover photo on a viewport-sized layer, so the crop is the same on a one-screen
   daily page and a four-screen weekly one. Does what background-attachment:
   fixed would, without its iOS Safari bugs. */
.menu-public::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: url("https://storage.googleapis.com/pej-app/pmd/eatery--image-1.png");
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
}

/* Logo. Height from the ratio, so a re-export letterboxes rather than crops. */
.menu-public::before {
  content: "";
  display: block;
  width: clamp(180px, 26vw, 320px);
  aspect-ratio: 5 / 3;
  margin: 0 auto;
  background-image: url("https://storage.googleapis.com/pej-app/pmd/eatery--logo-1.png");
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
}

/* ---- Typography ------------------------------------------------ */

h1,
h2,
h3,
h4,
h5,
p,
a,
.badge {
  font-family: "Roboto Slab", serif;
  font-style: normal;
  font-optical-sizing: auto;
}

h1,
.menu-public__menu-title {
  margin: 0;
  line-height: 1 !important; /* no token for heading leading */
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---- Dishes ---------------------------------------------------- */

/* Wider than the leading inside a dish, so a wrapped dish still reads as one.
   !important: --mp-space-row also drives the gap under the weekday. */
.menu-public .day__items {
  gap: clamp(0.9rem, 2.4vw, 1.4rem) !important;
}

/* The running line itself is the page's job — "Item description on the same
   line" under Layout settings. Setting display here would override the toggle. */
.item {
  margin: 0 auto;
}

.item__name {
  font-weight: 700;
  text-transform: uppercase;
}

.item__description,
.section__item__description {
  color: rgb(245 240 227 / 78%);
}

.menu-public .badge {
  display: block;
  width: fit-content;
  margin: clamp(0.35rem, 1.2vw, 0.6rem) auto 0;
  padding: 0.25em 0.9em;
  border-color: #f5f0e3;
  border-radius: 999px;
  font-size: clamp(0.6rem, 1.5vw, 0.8rem);
  font-weight: 600;
  letter-spacing: 0.14em;
  opacity: 1; /* the row is dimmed, the badge is not */
}

/* ---- Intro text ------------------------------------------------
   `.highlighted` on weekly, `__menu-description` on daily.        */

.highlighted {
  margin: clamp(1.5rem, 4vw, 2.5rem) auto;
  padding: 0;
}

.menu-public__menu-description {
  font-size: clamp(0.8rem, 2.3vw, 1.05rem) !important;
  line-height: 1.5 !important;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  opacity: 0.85;
  /* Keeps typed line breaks, blank lines included — press Enter twice to
     separate the thoughts in this text. */
  white-space: pre-line;
}

.highlighted .subtitle {
  margin: 0;
}

/* =================================================================
   WEEKLY ONLY
   ================================================================= */

/* text (left) | logo (centered) | empty (right) — the empty column balances the
   logo to dead center, as in the print layout. */
.menu-public--weekly {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  grid-template-areas:
    "title logo ."
    "week  logo ."
    "promo promo promo"
    "days  days  days";
  /* Row one is exactly the title: the h1 has line-height 1 and no margin, so the
     token is its height. It has to be a length, not min-content — the logo spans
     rows one and two and is far taller than the text, and a grid shares that
     surplus with every intrinsic row it spans. A fixed row is left out of the
     split, so all of it lands in row two and the week line sits right under the
     title instead of drifting down the page. */
  grid-template-rows: var(--mp-fs-h1) auto auto auto;
  align-items: center;
  /* Rows packed at the top. The page is min-height: 100vh, and the default
     `stretch` spread them over the whole viewport — a short week ended up with
     gaps between the header, the intro and the days. */
  align-content: start;
  column-gap: clamp(1rem, 4vw, 3rem);
  row-gap: 0;
}

.menu-public--weekly::before {
  grid-area: logo;
}

.menu-public--weekly h1 {
  grid-area: title;
  align-self: start;
  text-align: left;
}

.week {
  grid-area: week;
  align-self: start;
  margin: 0.2rem 0 0;
  letter-spacing: 0.16em;
  text-align: left;
  text-transform: uppercase;
  opacity: 0.9;
}

/* Disclaimer — injected, it isn't in the DOM. */
.week::after {
  content: "Med reservation för ev ändringar";
  display: block;
  margin-top: clamp(0.4rem, 1.2vw, 0.7rem);
  font-size: clamp(0.58rem, 1.4vw, 0.72rem);
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  opacity: 0.85;
}

.menu-public--weekly .highlighted {
  grid-area: promo;
}

/* !important: --mp-space-block also spaces above the first day. */
.menu-public .days {
  grid-area: days;
  gap: clamp(1.75rem, 4.5vw, 2.75rem) !important;
}

/* Full width on a row of its own, below the days. Without a column it was
   auto-placed into the first free cell — beside the logo, on row one, pushing
   everything else down with it. */
.menu-public--weekly .sections {
  grid-column: 1 / -1;
  margin-top: clamp(1.75rem, 4.5vw, 3rem);
}

.day__title {
  margin: 0 0 clamp(0.5rem, 1.6vw, 0.95rem);
  letter-spacing: 0.08em;
  text-transform: uppercase !important; /* beats the page's capitalize */
}

/* Inline before the weekday instead of hanging in the margin. */
.menu-public .is-today .day__title::before {
  display: inline-block;
  position: relative !important;
  top: clamp(0px, 1px, 3px) !important;
  left: -2vw !important;
}

/* Passed weekdays step back. There is no is-past class, so "past" is "has today
   after it"; at the weekend no day is today, and the whole week is behind us. */
.menu-public--weekly .day:has(~ .is-today),
.menu-public--weekly .days:not(:has(.is-today)) .day {
  opacity: 0.5;
}

.day:has(.day__temporary-closed) .day__title {
  color: #ac5e5e;
}

.day__temporary-closed,
.day__closed {
  color: #ac6363;
}

/* =================================================================
   DAILY AND CHANNELS ONLY
   ================================================================= */

.menu-public--daily {
  display: flex;
  flex-direction: column;
  align-items: stretch;

  --mp-fs-item-name: var(--mp-fs-p) !important;

  /* Bigger than in the weekly header, where it shares a row with the logo. Here
     it is centered on its own and has to outrank the dish names below it. */
  --mp-fs-h1: clamp(2rem, 5.5vw, 3.2rem);
}

.menu-public--daily::before {
  margin-bottom: clamp(0.75rem, 2.5vw, 1.5rem);
}

.menu-public--daily h1 {
  margin-bottom: clamp(0.5rem, 1.5vw, 0.9rem);
}

.menu-public__view-title {
  margin: clamp(1rem, 2.5vw, 1.5rem) 0 0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.menu-public__description {
  margin: clamp(0.4rem, 1.2vw, 0.7rem) 0 0;
  letter-spacing: 0.03em;
}

.menu-public__date {
  margin: 0.2rem 0 0;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
}

/* The date sits directly above now that the intro moved below the day. */
.menu-public--daily .day {
  margin-top: clamp(1.25rem, 3.5vw, 2.25rem);
}

/* Today's dishes: two lines each and white, where the rest of the page is cream.
   Tomorrow keeps the running line — hence :not(.day--next).
   !important: the page's inline rules match this selector's weight exactly. */
.menu-public--daily .day:not(.day--next) .item__name {
  display: block !important;
  font-size: clamp(1.25rem, 3.4vw, 1.9rem) !important;
  line-height: 1.15 !important;
  color: #fff;
}

.menu-public--daily .day:not(.day--next) .item__description {
  display: block !important;
  padding-top: 0.2em !important;
  color: rgb(255 255 255 / 85%);
}

.menu-public--daily .day:not(.day--next) .item__description::before {
  content: none !important;
}

.status {
  margin: clamp(1.5rem, 4vw, 2.5rem) 0 0;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.day__no-information {
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.8;
}

.menu-public--daily .sections {
  margin-top: clamp(1.75rem, 4.5vw, 3rem);
  gap: clamp(1.75rem, 4.5vw, 2.75rem) !important;
}

.section__title {
  margin: 0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.menu-public--daily .section__items {
  gap: clamp(0.6rem, 1.8vw, 1rem) !important;
}

.section__item__name {
  font-weight: 700;
  text-transform: uppercase;
}

/* ---- Tomorrow -------------------------------------------------- */

/* Separated by air and tone, no rule: a line read as two menus. */
.menu-public .day--next {
  --mp-space-next-day: clamp(2.5rem, 6vw, 4rem);

  opacity: 0.9;
}

.menu-public--daily .day--next {
  margin-top: 0;
}

/* A label, not a heading. */
.day--next .day__title {
  margin-bottom: 0.15rem;
  font-size: var(--mp-fs-p) !important;
  letter-spacing: 0.16em;
}

.day--next .menu-public__date {
  font-size: clamp(0.72rem, 1.8vw, 0.9rem);
}

.menu-public__loading {
  background-color: #315d6d !important;
}

/* =================================================================
   Mobile: stack the weekly header
   ================================================================= */

@media (max-width: 640px) {
  .menu-public--weekly {
    grid-template-columns: 1fr;
    grid-template-areas:
      "logo"
      "title"
      "week"
      "promo"
      "days";
    /* Every row back to auto. Row one is the logo here, not the title, and the
