  margin: 0 auto;
}

.item__name {
  font-weight: 700;
  text-transform: uppercase;
}

.item__description,
.section__item__description {
  color: rgb(245 240 227 / 78%);
}

.menu-public .badge {
  display: block;
  width: fit-content;
  margin: clamp(0.35rem, 1.2vw, 0.6rem) auto 0;
  padding: 0.25em 0.9em;
  border-color: #f5f0e3;
  border-radius: 999px;
  font-size: clamp(0.6rem, 1.5vw, 0.8rem);
  font-weight: 600;
