  grid-area: logo;
}

.menu-public--weekly h1 {
  grid-area: title;
  align-self: start;
  text-align: left;
}

.week {
  grid-area: week;
  align-self: start;
  margin: 0.2rem 0 0;
  letter-spacing: 0.16em;
  text-align: left;
  text-transform: uppercase;
  opacity: 0.9;
